From 3da8380d7eef2323474b3cf0fc931efe8b6656cb Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 22:09:22 +0100
Subject: [PATCH] dpms: don't wake the screens up when the mouse is barely
 moved

Any pointer motion turned the screens back on, so bumping the desk or
the mouse a little was enough to wake them up. Now the pointer has to
travel at least 50 pixels without pausing before the screens turn on.

BUG: 384768
---
 src/dpmsinputeventfilter.cpp | 18 +++++++++++++++++-
 src/dpmsinputeventfilter.h   |  3 +++
 2 files changed, 20 insertions(+), 1 deletion(-)

diff --git a/src/dpmsinputeventfilter.cpp b/src/dpmsinputeventfilter.cpp
index 2a6c54a017..afb44f3098 100644
--- a/src/dpmsinputeventfilter.cpp
+++ b/src/dpmsinputeventfilter.cpp
@@ -11,6 +11,7 @@
 #include "core/outputbackend.h"
 #include "input_event.h"
 #include "main.h"
+#include "pointer_input.h"
 #include "touch_input.h"
 #include "utils/keys.h"
 #include "utils/proximitysensor.h"
@@ -20,11 +21,14 @@
 #include <QGuiApplication>
 #include <QKeyEvent>

+#include <cmath>
+
 namespace KWin
 {

 DpmsInputEventFilter::DpmsInputEventFilter()
     : InputEventFilter(InputFilterOrder::Dpms)
+    , m_lastPointerPosition(input()->pointer()->pos())
 {
     // Touch up events are swallowed while this filter is installed, so a touch sequence
     // that started before the screens turned off would never end and block pointer focus
@@ -56,9 +60,21 @@ void DpmsInputEventFilter::updateProximitySensor()

 bool DpmsInputEventFilter::pointerMotion(PointerMotionEvent *event)
 {
-    if (!event->warp) {
+    if (event->warp) {
         // The intention is to wake the screen on user interactions
         // warp events aren't user interactions, so ignore them.
+        return true;
+    }
+
+    // Only wake up when the pointer was moved on purpose, not when the mouse got bumped
+    const QPointF delta = event->delta.isNull() ? event->position - m_lastPointerPosition : event->delta;
+    m_lastPointerPosition = event->position;
+    if (event->timestamp - m_lastPointerMotion > std::chrono::milliseconds(500)) {
+        m_pointerTravel = 0;
+    }
+    m_lastPointerMotion = event->timestamp;
+    m_pointerTravel += std::hypot(delta.x(), delta.y());
+    if (m_pointerTravel >= 50) {
         notify();
     }
     return true;
diff --git a/src/dpmsinputeventfilter.h b/src/dpmsinputeventfilter.h
index bbbed799b1..62e90c2f18 100644
--- a/src/dpmsinputeventfilter.h
+++ b/src/dpmsinputeventfilter.h
@@ -53,6 +53,9 @@ private:
     QElapsedTimer m_doubleTapTimer;
     QList<qint32> m_touchPoints;
     std::unique_ptr<ProximitySensor> m_sensor;
+    QPointF m_lastPointerPosition;
+    std::chrono::microseconds m_lastPointerMotion = std::chrono::microseconds::zero();
+    qreal m_pointerTravel = 0;

     bool m_secondTap = false;
     bool m_enableDoubleTap = false;
-- 
